// ══════════════════════════ navigation ══════════════════════════

const views = [...document.querySelectorAll("section[data-view]")];
const tabs = [...document.querySelectorAll(".tab")];
function go(name) {
  if (!views.some(v => v.dataset.view === name)) name = "accueil";
  views.forEach(v => v.classList.toggle("on", v.dataset.view === name));
  tabs.forEach(t => t.dataset.go === name ? t.setAttribute("aria-current", "page") : t.removeAttribute("aria-current"));
  if (location.hash.slice(1) !== name) history.replaceState(null, "", "#" + name);
  window.scrollTo({ top: 0 });
}
document.addEventListener("click", e => {
  const el = e.target.closest("[data-go]"); if (!el) return;
  e.preventDefault(); go(el.dataset.go);
});
window.addEventListener("hashchange", () => go(location.hash.slice(1) || "accueil"));

