// ══════════════════════════ mode picker (EAR / auto / CNN) ══════════════════════════

const MODE_NOTES = {
  auto: "L'EAR décide par défaut. Le CNN n'est consulté que sur les images où la géométrie est peu fiable.",
  ear: "Seule la géométrie décide. Aucun modèle à charger, vitesse de fermeture pleinement exploitable.",
  cnn: "Seul le réseau décide. Sa sortie sature : la vitesse de fermeture n'est plus exploitable seule.",
};

function renderModePicker(containerId, cnnAvailable) {
  const el = document.getElementById(containerId);
  const modes = cnnAvailable ? ["ear", "auto", "cnn"] : ["ear"];
  el.innerHTML = `
    <h3>Détection de l'œil</h3>
    <div class="seg" role="group" style="margin-top:10px">
      ${modes.map((m, i) => `<button data-mode="${m}" aria-pressed="${i === 0}">${
        { ear: "EAR seul", auto: "Automatique", cnn: "CNN seul" }[m]}</button>`).join("")}
    </div>
    <p class="modenote">${MODE_NOTES[modes[0]]}</p>
    ${!cnnAvailable ? '<p class="modeflag">CNN non chargé — sers cette page via un serveur local avec eye_cnn.onnx et eye_cnn_meta.json à côté du HTML pour activer Auto/CNN.</p>' : ""}
  `;
  el.dataset.mode = modes[0];
  el.querySelectorAll("[data-mode]").forEach(btn => {
    btn.addEventListener("click", () => {
      el.querySelectorAll("[data-mode]").forEach(b => b.setAttribute("aria-pressed", b === btn));
      el.dataset.mode = btn.dataset.mode;
      el.querySelector(".modenote").textContent = MODE_NOTES[btn.dataset.mode];
    });
  });
}

