// ══════════════════════════ MediaPipe : chargement une fois ══════════════════════════

let landmarkerPromise = null;
function getLandmarker() {
  if (!landmarkerPromise) {
    landmarkerPromise = (async () => {
      const { FaceLandmarker, FilesetResolver } = await import(MP_CDN + "/vision_bundle.mjs");
      const vision = await FilesetResolver.forVisionTasks(MP_CDN + "/wasm");
      return await FaceLandmarker.createFromOptions(vision, {
        baseOptions: { modelAssetPath: MP_MODEL_URL, delegate: "GPU" },
        runningMode: "VIDEO",
        numFaces: 1,
        minFaceDetectionConfidence: 0.5,
        minTrackingConfidence: 0.5,
      });
    })();
  }
  return landmarkerPromise;
}

// ══════════════════════════ CNN optionnel (ONNX) ══════════════════════════

function loadScriptTag(src) {
  return new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src = src; s.onload = resolve; s.onerror = reject;
    document.head.appendChild(s);
  });
}

let cnnState = { available: false, session: null, meta: null };

async function tryLoadCNN() {
  try {
    const metaResp = await fetch("./eye_cnn_meta.json");
    if (!metaResp.ok) throw new Error("meta introuvable");
    const meta = await metaResp.json();
    await loadScriptTag(ORT_CDN);
    ort.env.wasm.numThreads = 1; // évite l'avertissement crossOriginIsolated, sans impact perceptible ici
    const session = await ort.InferenceSession.create("./eye_cnn.onnx");
    cnnState = { available: true, session, meta };
    document.getElementById("cnn-status").textContent =
      `chargé — ${meta.img_size}×${meta.img_size}, seuil ${meta.threshold?.toFixed(3)}, température ${meta.temperature?.toFixed(2)}.`;
  } catch (e) {
    cnnState = { available: false, session: null, meta: null };
    document.getElementById("cnn-status").textContent =
      "non chargé (" + e.message + ") — mode EAR seul actif, pleinement fonctionnel.";
  }
  renderModePicker("mode-camera", cnnState.available);
}

/** Découpe un œil, le prépare (gris, resize, normalisation identique à eye_cnn_infer.py). */
function cropEyeTensor(videoEl, pts, ids, imgSize, pad) {
  const w = videoEl.videoWidth, h = videoEl.videoHeight;
  const xs = ids.map(i => pts[i][0] * w), ys = ids.map(i => pts[i][1] * h);
  const cx = (Math.min(...xs) + Math.max(...xs)) / 2, cy = (Math.min(...ys) + Math.max(...ys)) / 2;
  const half = Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys)) * (1 + pad) / 2;
  const off = document.createElement("canvas");
  off.width = imgSize; off.height = imgSize;
  const ctx = off.getContext("2d");
  ctx.drawImage(videoEl, cx - half, cy - half, half * 2, half * 2, 0, 0, imgSize, imgSize);
  const { data } = ctx.getImageData(0, 0, imgSize, imgSize);
  const out = new Float32Array(imgSize * imgSize);
  for (let i = 0; i < imgSize * imgSize; i++) {
    const gray = (data[i * 4] * 0.299 + data[i * 4 + 1] * 0.587 + data[i * 4 + 2] * 0.114) / 255;
    out[i] = (gray - 0.5) / 0.5;
  }
  return out;
}

/** Rend p_closed moyen (yeux gauche+droit) via le CNN, ou null si indisponible. */
async function cnnProbaClosed(videoEl, pts) {
  if (!cnnState.available) return null;
  const { img_size, crop_pad, class_to_idx, temperature } = cnnState.meta;
  const closedIdx = class_to_idx.closed ?? 0;
  const left = cropEyeTensor(videoEl, pts, LEFT_EYE, img_size, crop_pad);
  const right = cropEyeTensor(videoEl, pts, RIGHT_EYE, img_size, crop_pad);
  const batch = new Float32Array(img_size * img_size * 2);
  batch.set(left, 0); batch.set(right, img_size * img_size);
  const tensor = new ort.Tensor("float32", batch, [2, 1, img_size, img_size]);
  const out = await cnnState.session.run({ [cnnState.session.inputNames[0]]: tensor });
  const logits = out[cnnState.session.outputNames[0]].data; // [2,2]
  const probs = [];
  for (let r = 0; r < 2; r++) {
    const a = logits[r * 2] / temperature, b = logits[r * 2 + 1] / temperature;
    const m = Math.max(a, b);
    const ea = Math.exp(a - m), eb = Math.exp(b - m);
    probs.push((closedIdx === 0 ? ea : eb) / (ea + eb));
  }
  return (probs[0] + probs[1]) / 2;
}

// ══════════════════════════ boucle d'analyse partagée ══════════════════════════

function drawStrip(stripEl, cls) {
  const i = document.createElement("i"); i.className = cls; stripEl.appendChild(i);
  while (stripEl.children.length > 240) stripEl.removeChild(stripEl.firstChild);
}

function clsForState(state, microsleep) {
  if (microsleep) return "s";
  if (state === "closed") return "d";
  return "a";
}

// ══════════════════════════ overlay landmarks (canvas au-dessus de la vidéo) ══════════════════════════

/** Dessine les points MediaPipe sur le canvas superposé à la vidéo (bug corrigé :
 * le canvas existait dans le markup mais rien n'y dessinait jamais). */
function drawLandmarks(canvas, videoEl, pts) {
  if (canvas.width !== videoEl.videoWidth || canvas.height !== videoEl.videoHeight) {
    canvas.width = videoEl.videoWidth || 640;
    canvas.height = videoEl.videoHeight || 480;
  }
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "rgba(45,212,191,.55)"; // teal, discret
  for (let i = 0; i < pts.length; i++) {
    ctx.beginPath();
    ctx.arc(pts[i][0] * canvas.width, pts[i][1] * canvas.height, 1.1, 0, Math.PI * 2);
    ctx.fill();
  }
  const highlight = (ids, color) => {
    ctx.strokeStyle = color; ctx.lineWidth = 1.6; ctx.beginPath();
    ids.forEach((id, i) => {
      const [x, y] = [pts[id][0] * canvas.width, pts[id][1] * canvas.height];
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.closePath(); ctx.stroke();
  };
  highlight(LEFT_EYE, "#2DD4BF"); highlight(RIGHT_EYE, "#2DD4BF");
}

// ══════════════════════════ alertes sonores micro-sommeil ══════════════════════════

let audioCtx = null;
function beep(freq, durationMs, gainVal) {
  try {
    audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
    const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    osc.frequency.value = freq; osc.type = "sine";
    gain.gain.value = gainVal;
    osc.connect(gain); gain.connect(audioCtx.destination);
    osc.start();
    gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + durationMs / 1000);
    osc.stop(audioCtx.currentTime + durationMs / 1000 + 0.02);
  } catch (e) { /* audio indisponible (autoplay bloqué avant interaction) : on ignore */ }
}

function speak(text) {
  if (!("speechSynthesis" in window)) return;
  const u = new SpeechSynthesisUtterance(text);
  u.lang = "fr-FR"; u.rate = 1.0;
  window.speechSynthesis.speak(u);
}

/** État d'alerte persistant sur une session (cooldowns pour ne pas spammer). */
function newAlertAudioState() {
  return { lastLevel: "none", lastSpokenOrange: -Infinity, lastSpokenRouge: -Infinity };
}

const ALERT_COOLDOWN_ORANGE_S = 6;
const ALERT_COOLDOWN_ROUGE_S = 4;

function triggerAlertAudio(audioState, level, t) {
  if (level === "orange") {
    if (level !== audioState.lastLevel || t - audioState.lastSpokenOrange >= ALERT_COOLDOWN_ORANGE_S) {
      beep(660, 220, 0.05);
      speak("Attention, microsommeil.");
      audioState.lastSpokenOrange = t;
    }
  } else if (level === "rouge") {
    if (level !== audioState.lastLevel || t - audioState.lastSpokenRouge >= ALERT_COOLDOWN_ROUGE_S) {
      beep(440, 380, 0.08);
      speak("Ralentissez et arrêtez-vous en sécurité.");
      audioState.lastSpokenRouge = t;
    }
  }
  audioState.lastLevel = level;
}

const ALERT_LABEL = { jaune: "Micro-sommeil (léger)", orange: "Micro-sommeil (modéré)", rouge: "Micro-sommeil critique" };

/** Met à jour tout le panneau de droite (dial + reason + 6 mini-cartes + strip)
 * à partir d'un instantané de mesures. */
function renderMetrics(dash, ear, mar, yaw, pitch, pClosed, state) {
  const q = sel => dash.querySelector(sel);
  const panel = q("[data-panel-alert]");
  panel.dataset.alert = state.alertLevel !== "none" ? state.alertLevel : "";

  q("[data-tag]").hidden = false; q("[data-status]").hidden = false;
  q("[data-tag]").textContent = state.eyeState ? state.eyeState.toUpperCase() : "—";
  q("[data-status]").textContent = state.source === "cnn" ? "source: CNN" : "source: EAR";

  if (state.alertLevel !== "none") {
    q("[data-state]").textContent = ALERT_LABEL[state.alertLevel];
    q("[data-reason]").textContent = `Fermé depuis ${state.closedDuration.toFixed(1)}s — EAR ${ear.toFixed(2)}, seuil ${state.thrClosed?.toFixed(2) ?? "—"}.`;
  } else if (state.yawning) {
    q("[data-state]").textContent = "Bâillement";
    q("[data-reason]").textContent = `MAR ${mar.toFixed(2)} (seuil ${CFG.marYawn.toFixed(2)}) — bouche ouverte en continu.`;
  } else if (state.source === "cnn") {
    q("[data-state]").textContent = state.eyeState === "closed" ? "Yeux fermés (CNN)" : "Vigilant";
    q("[data-reason]").textContent = `CNN : yeux ouverts à ${Math.round((state.openness ?? 0) * 100)}% (p. fermé ${pClosed !== null ? pClosed.toFixed(2) : "—"}).`;
  } else {
    q("[data-state]").textContent = state.eyeState === "closed" ? "Yeux fermés" : "Vigilant";
    q("[data-reason]").textContent = `EAR ${ear.toFixed(2)}, PERCLOS ${(state.perclos*100).toFixed(0)}%, angle ${yaw.toFixed(0)}°.`;
  }

  if (state.score !== null) {
    q("[data-score]").textContent = Math.round(state.score);
    const off = 270 - 270 * (state.score / 100);
    const arc = q("[data-arc]"); arc.style.strokeDashoffset = off;
    arc.style.stroke = state.alertLevel === "rouge" ? "var(--coral)" : state.alertLevel === "orange" ? "#E8A33D"
      : state.alertLevel === "jaune" ? "#E8C33D" : state.score < 40 ? "var(--coral)" : state.score < 70 ? "#E8A33D" : "var(--teal)";
  }

  q("[data-m-ear]").textContent = ear.toFixed(2);
  q("[data-mini-ear]").classList.toggle("dim", state.source === "cnn");

  const cnnActive = state.source === "cnn" || pClosed !== null;
  q("[data-m-cnn]").textContent = cnnActive ? Math.round((state.openness ?? (1 - pClosed)) * 100) + "%" : "—";
  q("[data-mini-cnn]").classList.toggle("dim", !cnnActive);

  q("[data-m-yawn]").textContent = mar.toFixed(2);
  q("[data-mini-yawn]").classList.toggle("flag", state.yawning);

  q("[data-m-blink]").textContent = Math.round(state.blinksPerMin);
  q("[data-m-perclos]").textContent = Math.round(state.perclos * 100) + "%";
  const yawReliable = Math.abs(yaw) < CFG.yawAwayDeg && Math.abs(pitch) < CFG.pitchDownDeg;
  q("[data-m-yaw]").textContent = (yaw > 0 ? "+" : "") + yaw.toFixed(0) + "°" + (yawReliable ? "" : " ⚠");
  q("[data-mini-yaw]").classList.toggle("flag", !yawReliable);

  drawStrip(q("[data-strip]"), clsForState(state.eyeState, state.microsleep));
}

/** Un pas d'analyse : détecte, calcule EAR/MAR/pose, interroge le CNN si actif, met à jour l'UI.
 * `audioState` (optionnel) porte les cooldowns des alertes sonores. `timeline` (optionnel)
 * reçoit un instantané complet par frame — landmarks inclus — pour permettre un replay fidèle. */
async function analyzeFrame(videoEl, landmarker, ta, mode, t, dash, scoreHist, audioState, timeline) {
  const res = landmarker.detectForVideo(videoEl, performance.now());
  const q = sel => dash.querySelector(sel);
  q("[data-ph]").hidden = true;
  const canvas = q("[data-canvas]");

  if (!res.faceLandmarks.length) {
    const state = ta.update(t, false, null, null, null, null);
    q("[data-tag]").hidden = false; q("[data-status]").hidden = false;
    q("[data-tag]").textContent = "Visage non détecté";
    q("[data-status]").textContent = "—";
    drawStrip(q("[data-strip]"), "c");
    if (canvas.getContext) canvas.getContext("2d").clearRect(0, 0, canvas.width, canvas.height);
    return state;
  }
  const pts = res.faceLandmarks[0].map(p => [p.x, p.y, p.z]);
  const ear = earBoth(pts), mar = mouthAspectRatio(pts);
  const { yaw, pitch } = headPose(pts);
  canvas.hidden = false;
  drawLandmarks(canvas, videoEl, pts);

  let openness = null, source = "ear", pClosed = null;
  if ((mode === "cnn" || mode === "auto") && cnnState.available) {
    pClosed = await cnnProbaClosed(videoEl, pts);
    if (mode === "cnn") { openness = 1 - pClosed; source = "cnn"; }
    else {
      const low = 0.35, high = 0.65; // CFG.cnnUncertainLow/High
      if (pClosed < low || pClosed > high) { openness = 1 - pClosed; source = "cnn"; }
    }
  }

  const state = ta.update(t, true, ear, mar, yaw, pitch, openness, source);
  if (state.score !== null) scoreHist.push(state.score);
  if (audioState) triggerAlertAudio(audioState, state.alertLevel, t);
  // xy seulement (z inutile pour le dessin) : ~2/3 de mémoire en moins pour le replay
  if (timeline) timeline.push({ t, ear, mar, yaw, pitch, pClosed, pts: pts.map(p => [p[0], p[1]]), state });

  renderMetrics(dash, ear, mar, yaw, pitch, pClosed, state);
  return state;
}

function renderReport(container, ta, scoreHist) {
  const events = ta.events;
  const micro = events.filter(e => e.kind === "microsleep");
  const lookAway = events.filter(e => e.kind === "look_away");
  const longBlinks = events.filter(e => e.kind === "long_blink");
  const avg = scoreHist.length ? scoreHist.reduce((a, b) => a + b, 0) / scoreHist.length : null;

  let verdict, detail;
  if (micro.length) {
    const worst = micro.reduce((a, b) => (b.duration > a.duration ? b : a));
    verdict = "Vigilance dégradée : un micro-sommeil confirmé";
    detail = `Fermeture de ${worst.duration.toFixed(1)}s à ${worst.tStart.toFixed(1)}s, sévérité ${worst.severity}, source ${worst.source}.`;
  } else if (lookAway.length || longBlinks.length) {
    verdict = "Vigilance globalement correcte, quelques signaux à surveiller";
    detail = `${longBlinks.length} clignement(s) long(s), ${lookAway.length} sortie(s) de route.`;
  } else {
    verdict = "Vigilance nominale sur toute la session";
    detail = "Aucun événement notable détecté.";
  }

  const tiles = [
    ["Vigilance moyenne", avg !== null ? Math.round(avg) + "/100" : "—"],
    ["Micro-sommeils", micro.length],
    ["Regards hors route", lookAway.length],
    ["Clignements longs", longBlinks.length],
  ].map(([k, v]) => `<div class="tile"><div class="k">${k}</div><div class="v">${v}</div></div>`).join("");

  const chaps = events.map(e => {
    const pillCls = { critique: "no", modere: "mid", info: "ok" }[e.severity] || "ok";
    return `<div class="chap"><div class="t">${e.tStart.toFixed(1)}s</div><div class="x">
      <span class="pill ${pillCls}">${e.kind} — ${e.duration.toFixed(2)}s</span>
      <small>Source : ${e.source}, sévérité : ${e.severity}</small></div></div>`;
  }).join("");

  container.hidden = false;
  container.innerHTML = `
    <div class="verdict"><div class="lab">Verdict</div><div class="big">${verdict}</div>
      <p class="dim" style="margin-top:10px;font-size:.9rem">${detail}</p></div>
    <div class="mrow" style="margin-top:14px">${tiles}</div>
    ${events.length ? `<h3 style="margin:26px 0 4px;font-size:1.15rem">Déroulé</h3>${chaps}`
                    : '<p class="dim" style="margin-top:16px">Aucun événement.</p>'}
  `;
}

// ══════════════════════════ onglet caméra ══════════════════════════

const runCameraBtn = document.getElementById("run-camera");
const dashCamera = document.getElementById("dash-camera");
let sessionDuration = 30;
document.getElementById("seg-duration").addEventListener("click", e => {
  const b = e.target.closest("button"); if (!b) return;
  [...e.currentTarget.children].forEach(c => c.setAttribute("aria-pressed", c === b));
  sessionDuration = parseInt(b.dataset.dur, 10);
});

// ─── Confidentialité caméra ──────────────────────────────────────────────
// Aucun appel fetch/XHR/WebSocket n'existe dans ce fichier pour le flux
// caméra : les images ne quittent jamais l'appareil (vérifiable en lisant ce
// fichier). Rien n'est écrit sur disque, en localStorage, sessionStorage ou
// IndexedDB. Aucune piste audio n'est demandée à getUserMedia. Le flux caméra
// (`stream`) est explicitement arrêté (`getTracks().forEach(tr => tr.stop())`)
// dès la fin de la session, ce qui coupe le témoin caméra du système.
// Seules des métriques numériques agrégées (scores, EAR, etc.) existent le
// temps de la session, en mémoire JS, puis sont perdues à la fermeture ou à
// la navigation — rien n'est conservé, ni côté client ni côté serveur.

runCameraBtn.addEventListener("click", async () => {
  runCameraBtn.disabled = true;
  const mode = document.getElementById("mode-camera").dataset.mode || "ear";
  const videoEl = dashCamera.querySelector("[data-video]");
  let stream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" } });
  } catch (e) {
    dashCamera.querySelector("[data-ph]").textContent = "Caméra refusée ou indisponible : " + e.message;
    runCameraBtn.disabled = false;
    return;
  }
  videoEl.hidden = false; videoEl.srcObject = stream;
  await new Promise(r => videoEl.onloadedmetadata = r);
  videoEl.play();

  const landmarker = await getLandmarker();
  const ta = new TemporalAnalyzer(CFG, cnnState.meta?.threshold ?? null);
  const scoreHist = [];
  const audioState = newAlertAudioState();
  const t0 = performance.now();

  await new Promise(resolve => {
    const step = async () => {
      const elapsed = (performance.now() - t0) / 1000;
      if (elapsed >= sessionDuration) { resolve(); return; }
      await analyzeFrame(videoEl, landmarker, ta, mode, elapsed, dashCamera, scoreHist, audioState);
      dashCamera.querySelector("[data-bar]").style.width = Math.min(100, (elapsed / sessionDuration) * 100) + "%";
      dashCamera.querySelector("[data-clock]").textContent = elapsed.toFixed(0) + "s";
      requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  });

  stream.getTracks().forEach(tr => tr.stop());
  ta.finalize(sessionDuration);
  renderReport(document.getElementById("report-camera"), ta, scoreHist);
  runCameraBtn.disabled = false;
});

